CREATE TABLE "comments" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "post_id" BIGINT NOT NULL REFERENCES "posts" ("id"),
    "user_id" BIGINT NOT NULL,
    "content" TEXT NOT NULL,
    "deleted_at" TIMESTAMP,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL
);

CREATE INDEX "idx_comments_post_id" ON "comments" ("post_id", "id");

CREATE TABLE "comment_closures" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ancestor_id" BIGINT NOT NULL REFERENCES "comments" ("id"),
    "descendant_id" BIGINT NOT NULL REFERENCES "comments" ("id"),
    "depth" INT NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    UNIQUE ("ancestor_id", "descendant_id")
);

CREATE INDEX "idx_comment_closures_descendant" ON "comment_closures" ("descendant_id", "depth");
